    song = apis.spotify.show_song(song_id=sid)
    genre = song.get('genre')
    if isinstance(genre,str) and genre.lower()=='classical':
        classical_songs.append({
            'song_id': sid,
            'title': song.get('title'),
            'album_title': song.get('album_title'),
            'artists': [{'artist_id': a.get('id'), 'name': a.get('name')} for a in song.get('artists',[])]
        })
print('total unique songs', len(all_song_ids_list))
print('classical songs count', len(classical_songs))
print('classical songs sample', classical_songs[:5])
# collect target artist ids
classical_artist_ids=set()
for cs in classical_songs:
    for a in cs['artists']:
        if a['artist_id'] is not None:
            classical_artist_ids.add(a['artist_id'])
print('unique classical artist ids', len(classical_artist_ids))
print('classical artist ids sample', sorted(classical_artist_ids)[:20])

# Verification table for classical songs and their artists
print('Classical songs count:', len(classical_songs))
